import {TEXT_LIMIT} from './import-limits.js';
import {escapeHtml as e,validateOrder,parseOrderText,localDateTime} from './core.js';
import {messages,interfaceLanguages,resolveLanguage,languageConfig,recognitionText} from './i18n.js';
import {getAIStatus,recognizeWithAI} from './ai-adapter.js';
import {documentMessages} from './document-i18n.js';
import {operationsMessages} from './operations-i18n.js';
import {isActiveOrder,isWaitingOrder,sortOrders} from './merchant-operations.js';
import {createMerchantOperationsUI} from './merchant-operations-ui.js';
import {documentField,wireDocumentImport} from './document-import.js';
import {createMenuImportUI} from './menu-import-ui.js';
import {needsItemReview,applyItemReview,findMenuDish,suggestedMenuName} from './order-review.js';
import {batchDraftIssue,prepareBatchOrders} from './batch-orders.js';
import {cleanAliases,conflictingDish} from './menu-matching.js';
import {deliveryWindow,deliveryWindowLabel,deliverySlotOptions,slotForTime,validLocalMinute} from './delivery-slots.js';

import {materialUnits,recipeRows,validateRecipe,snapshotItem,freezeOrderMaterials,aggregateMaterials,materialOrders} from './materials.js';

import {cloudRequest} from './cloud-api.js';
import {preparationEstimate,orderTiming} from './order-timing.js';
import {createBuyerUI} from './buyer-ui.js';
import {buyerMessages} from './buyer-i18n.js';
import {menuExportMessages} from './menu-export-i18n.js';
import {openMenuExport} from './menu-export-ui.js';
import {pricingFields,wirePricingEditor,readPricing} from './catalog-editor.js';
import {money,cnyReference,optionText,validCents} from './commerce.js';
for(const lang of ['zh','en','ms'])Object.assign(messages[lang],buyerMessages[lang],menuExportMessages[lang],documentMessages[lang],operationsMessages[lang]);
let portal;try{portal=sessionStorage.getItem('orderweave-portal')||'merchant';}catch{portal='merchant';}
const itemLabel=i=>e(i.name)+(optionText(i)?' <small>'+e(optionText(i))+'</small>':'');
const dualMoney=(value,currency='MYR')=>e(money(value,languageConfig(language).locale,currency))+(currency==='MYR'?' <small class="cny-price">≈ '+e(money(cnyReference(value),languageConfig(language).locale,'CNY'))+'</small>':'');
function buyerPayment(o){return o.source==='buyer'?'<div class="notice buyer-order-info"><b>'+t('buyerSource')+' · '+dualMoney(o.totalCents,o.currency)+'</b><br>'+t(o.payment.method)+' · '+t(o.payment.status)+'</div>':'';}

const KEY='takeaway-desk-v1',LANG='takeaway-desk-language',SESSION='takeaway-desk-session';
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),confirmation=document.querySelector('#confirmation');
let language='zh',languageChosen=false,db={accounts:[]},raw=null,locked=false,currentId=null,view='orders',filter='active',search='',authMode='login',toastTimer,photo='',confirmCallback=null;
const t=key=>messages[language][key]||key;
const rt=value=>recognitionText(value,language);
const uid=()=>crypto.randomUUID();
let orderSort='scheduledAt',orderDirection='asc';
let pendingBatch=null,materialScope='current',memberships=[],identity=null,booting=true,cloudError='',revision=0,saving=false,legacyDb={accounts:[]},legacyCount=0,logsCursor=null;
const cloudSession='orderweave-demo-store';
const account=()=>db.accounts.find(a=>a.id===currentId);

try{language=resolveLanguage(localStorage.getItem(LANG));languageChosen=!!localStorage.getItem(LANG);const local=localStorage.getItem(KEY);if(local){const parsed=JSON.parse(local);if(Array.isArray(parsed.accounts))legacyDb=parsed;}}catch{locked=true;}
function toast(text){const box=document.querySelector('#toast');box.textContent=text;box.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('show'),5000);}
const cloudMessage=error=>messages[language]['cloud_'+error.message]||t('cloud_SERVER_ERROR');
async function logEvent(event,target=''){if(!currentId)return;try{await cloudRequest({action:'event',merchantId:currentId,event,target});}catch(err){toast(t('logSaveFailed'));}}
function acceptState(state){currentId=state.id;revision=state.revision;db={accounts:[state]};try{sessionStorage.setItem(cloudSession,currentId);}catch{}}
async function saveAccount(data,migrating=false,extra={}){
  if(saving){toast(t('busy'));return false;}saving=true;
  try{const state=await cloudRequest({action:migrating?'migrate':'save',merchantId:currentId,expectedRevision:revision,menu:data.menu,orders:data.orders,...extra});acceptState(state);return true;}
  catch(error){toast(cloudMessage(error));if(error.message==='CONFLICT'){modal.close();confirmation.close();pendingBatch=null;await refreshState(true);}return false;}
  finally{saving=false;}
}
async function refreshState(force=false){if(portal==='buyer')return;if(!currentId||(saving&&!force))return;try{const state=await cloudRequest({},'?merchantId='+encodeURIComponent(currentId));if(!force&&(modal.open||confirmation.open))return;const changed=state.revision!==revision;acceptState(state);if(force||changed)render();}catch(error){if(['AUTH_REQUIRED','MEMBERSHIP_REQUIRED'].includes(error.message)){modal.close();confirmation.close();confirmCallback=null;pendingBatch=null;currentId=null;db={accounts:[]};sessionStorage.removeItem(cloudSession);await bootstrap(false);toast(cloudMessage(error));}}}
async function openStore(id){const state=await cloudRequest({},'?merchantId='+encodeURIComponent(id));acceptState(state);view='orders';filter='active';search='';await logEvent('login');render();if(!state.menu.length)menuWelcome();}
async function bootstrap(restore=true){if(portal==='buyer'){booting=false;await buyerApp.start();return;}booting=true;render();try{const result=await cloudRequest();identity=result.identity;memberships=result.memberships;legacyCount=result.legacyAccountCount||0;cloudError='';booting=false;const selected=restore?sessionStorage.getItem(cloudSession):null;if(selected&&memberships.some(m=>m.merchantId===selected))await openStore(selected);else render();}catch(error){booting=false;cloudError=cloudMessage(error);render();}}
function langSelect(){return `<select class="lang-control" data-action="language" aria-label="${t('selectLanguage')}">${interfaceLanguages.map(l=>`<option value="${l.code}" ${language===l.code?'selected':''}>${e(l.label)}</option>`).join('')}</select>`;}
function brand(){return `<div class="brand"><span class="brand-mark" aria-hidden="true">≋</span>${t('brand')}</div>`;}
function button(action,label,classes='',extra=''){return `<button type="button" class="${classes}" data-action="${action}" ${extra}>${label}</button>`;}
function empty(title,sub,action,label){return `<div class="empty"><div class="empty-icon" aria-hidden="true">▤</div><h3>${t(title)}</h3><p>${t(sub)}</p>${action?button(action,t(label),'primary'):''}</div>`;}
function render(){if(portal==='buyer'){buyerApp.render();return;}document.documentElement.lang=languageConfig(language).lang;document.title=t('brand')+' · '+(currentId?t(view):t('login'));if(!currentId)renderAuth();else renderWorkspace();}


function renderAuth(){
 const mode=authMode,credentials=`${input('username',t('demoUsername'),'text','',true,'','minlength="2" maxlength="60" autocomplete="username"')}${input('password',t('password'),'password','',true,'',`minlength="6" maxlength="200" autocomplete="${mode==='login'?'current-password':'new-password'}"`)}${mode!=='login'?input('repeatPassword',t('repeatPassword'),'password','',true,'','minlength="6" maxlength="200" autocomplete="new-password"'):''}`;
 app.innerHTML=`<main class="auth cloud-auth"><section class="auth-story">${brand()}<div><div class="eyebrow">${t('demoBadge')}</div><div class="story-title">${t('cloudWelcome')}</div><p class="story-text">${t('cloudLoginHelp')}</p></div><small>${t('demoDataNotice')}</small></section><section class="auth-side"><div class="auth-card">${langSelect()}<div class="row wrap portal-choice">${button('buyer-enter',t('buyerLogin'))}<span class="badge">${t('merchantLogin')}</span></div><div class="eyebrow">${t('demoBadge')}</div><h1>${t('cloudWelcome')}</h1>${booting?`<p role="status">${t('busy')}</p>`:cloudError?`<p class="error" role="alert">${e(cloudError)}</p>${button('retry-demo',t('retryLocal'),'primary')}`:!languageChosen?`<p>${t('chooseSub')}</p>${button('continue-language',t('continue'),'primary')}`:`<div class="auth-tabs">${['login','register','join'].map(key=>button('auth-'+key,t(key==='login'?'enterStore':key==='register'?'createStore':'joinStore'),mode===key?'active':'')).join('')}</div><form id="cloud-auth-form">${mode==='register'?input('shop',t('shop'),'text','',true,'','maxlength="100"')+input('operatorName',t('operatorName'),'text','',true,'','maxlength="80"'):mode==='join'?input('code',t('inviteCode'),'text','',true,'','maxlength="100" autocomplete="off"')+input('operatorName',t('operatorName'),'text','',true,'','maxlength="80"'):''}${credentials}<p id="auth-error" class="error" role="alert"></p><button type="submit" class="primary">${t(mode==='login'?'enterStore':mode==='register'?'createStore':'joinStore')}</button></form><p class="auth-footer">${t('cloudLoginHelp')}</p>${legacyCount?`<p class="notice">${t('localMigrationAvailable')}</p>`:''}`}</div></section></main>`;
 document.querySelector('#cloud-auth-form')?.addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(event.currentTarget),submit=event.currentTarget.querySelector('[type=submit]');submit.disabled=true;try{const state=await cloudRequest({action:mode==='login'?'login':mode==='register'?'create':'join',shop:data.get('shop'),operatorName:data.get('operatorName'),code:String(data.get('code')||'').trim(),username:data.get('username'),password:data.get('password'),repeatPassword:data.get('repeatPassword')});await openStore(state.id);if(mode==='register')await showOperators();}catch(error){const box=document.querySelector('#auth-error');if(box)box.textContent=cloudMessage(error);}finally{submit.disabled=false;}});
}
function input(name,label,type='text',value='',required=false,placeholder='',extra=''){return `<div class="field"><label for="f-${name}">${label}${!required?` <span class="muted">(${t('optional')})</span>`:''}</label><input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${required?'required':''} placeholder="${e(placeholder)}" ${extra}></div>`;}
function textarea(name,label,value='',required=false,extra=''){return `<div class="field"><label for="f-${name}">${label}${!required?` <span class="muted">(${t('optional')})</span>`:''}</label><textarea id="f-${name}" name="${name}" ${required?'required':''} ${extra}>${e(value)}</textarea></div>`;}
async function passwordHash(password,salt){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new Uint8Array(salt),iterations:150000,hash:'SHA-256'},material,256);return Array.from(new Uint8Array(bits),n=>n.toString(16).padStart(2,'0')).join('');}
function renderWorkspace(){const a=account();if(!a){currentId=null;render();return}app.innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<nav aria-label="${t('brand')}"><button data-action="nav-orders" class="${view==='orders'?'active':''}"><span class="nav-icon" aria-hidden="true">▤</span>${t('orders')}</button><button data-action="nav-menu" class="${view==='menu'?'active':''}"><span class="nav-icon" aria-hidden="true">▦</span>${t('menu')}</button><button data-action="nav-materials" class="${view==='materials'?'active':''}"><span class="nav-icon" aria-hidden="true">◫</span>${t('materials')}</button><button data-action="nav-kitchen" class="${view==='kitchen'?'active':''}"><span class="nav-icon" aria-hidden="true">▥</span>${t('kitchen')}</button></nav><div class="sidebar-bottom"><div><div class="account">${e(a.shop)}</div><p class="muted">${e(a.operator.name)} · ${t('role_'+a.operator.role)}</p></div><div class="row">${button('buyer-enter',t('buyerLogin'),'small ghost')}${button('open-logs',t('operationLogs'),'small ghost')}${button('open-operators',t('operators'),'small ghost')}${button('export',t('backup'),'small ghost')}${button('logout',t('logout'),'small ghost')}</div></div></aside><main class="workspace"><div class="notice demo-notice">${t('demoDataNotice')}</div><div class="topbar"><span><span class="dot"></span>${t('cloudStorage')}</span>${langSelect()}</div>${view==='orders'?orderPage(a):view==='materials'?materialsPage(a):view==='kitchen'?opsUI.kitchenPage(a):menuPage(a)}<p class="local-note">${t('cloudFoot')}</p></main></div>`;updateOrderTiming();document.querySelector('[data-action=search]')?.addEventListener('input',ev=>{search=ev.target.value;renderOrderList();});}
function orderPage(a){const today=localDateTime(new Date()).slice(0,10),active=a.orders.filter(isActiveOrder).length,scheduled=a.orders.filter(o=>isActiveOrder(o)&&o.scheduledAt.slice(0,10)===today).length,delivered=a.orders.filter(o=>o.deliveredAt&&localDateTime(o.deliveredAt).slice(0,10)===today).length;return `<header class="page-head"><div><div class="eyebrow">${t('tag')}</div><h1>${t('orderTitle')}</h1><p>${t('orderSubtitle')}</p></div>${button('add-order',t('addOrder')+(a.orders.some(isWaitingOrder)?`<span class="notification-count" aria-hidden="true">${a.orders.filter(isWaitingOrder).length}</span><span class="sr-only"> · ${t('pendingBuyerOrders')}: ${a.orders.filter(isWaitingOrder).length}</span>`:''),'primary add-order-button')}</header>${opsUI.hoursCard(a)}<section class="stats" aria-label="${t('orders')}">${[['activeCount',active],['scheduledCount',scheduled],['deliveredCount',delivered]].map(([label,value])=>`<div class="stat"><div class="stat-label">${t(label)}</div><div class="stat-value">${value}<span>${t('unitOrder')}</span></div></div>`).join('')}</section><div class="tools"><div class="filters" aria-label="${t('status')}">${['active','all','completed'].map(f=>button('filter',t(f)+(f==='active'?` · ${active}`:''),filter===f?'active':'',`data-filter="${f}" aria-pressed="${filter===f}"`)).join('')}</div><label class="order-sort">${t('orderSort')}<select data-order-sort>${['scheduledAt','createdAt','location','deliveredAt'].map(k=>`<option value="${k}" ${orderSort===k?'selected':''}>${t('sort_'+k)}</option>`).join('')}</select></label><label class="order-sort">${t('sortDirection')}<select data-order-direction><option value="asc" ${orderDirection==='asc'?'selected':''}>${t('sortAsc')}</option><option value="desc" ${orderDirection==='desc'?'selected':''}>${t('sortDesc')}</option></select></label><input class="search" type="search" data-action="search" value="${e(search)}" placeholder="${t('search')}" aria-label="${t('search')}"></div><section id="order-list" class="orders" aria-label="${t('orders')}">${orderList()}</section>`;}
function orderList(){const filtered=account().orders.filter(o=>(filter==='all'||(filter==='completed'?o.status==='delivered':isActiveOrder(o)))&&  (o.number+' '+o.customer+' '+o.location+' '+o.contact+' '+o.items.map(i=>i.name).join(' ')).toLowerCase().includes(search.toLowerCase()));const list=sortOrders(filtered,orderSort,orderDirection,languageConfig(language).locale);if(!list.length)return empty(account().orders.length?'noResults':'emptyOrders',account().orders.length?'noResultsSub':'emptyOrdersSub',account().orders.length?'':'add-order','addOrder');return list.map(orderCard).join('');}
function renderOrderList(){document.querySelector('#order-list').innerHTML=orderList();}
function date(value){if(!value)return '—';return new Date(value).toLocaleString(languageConfig(language).locale,{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});}
function schedule(o){return deliveryWindowLabel(o,languageConfig(language).locale,t('nextDay'));}
function originalSchedule(o){const value=o.originalScheduledAt||(deliveryWindow(o)?.scheduledAt!==o.scheduledAt?o.scheduledAt:'');return value?(validLocalMinute(value)?date(value):value)+(o.originalScheduledEndAt?' – '+(validLocalMinute(o.originalScheduledEndAt)?date(o.originalScheduledEndAt):o.originalScheduledEndAt):''):'';}
function scheduleInputs(o,isDraft){
  const window=deliveryWindow(o),dateValue=window?.scheduledAt.slice(0,10)||o.originalScheduledAt?.slice(0,10)||(!isDraft&&!o.id?localDateTime(new Date()).slice(0,10):'');
  return `<div class="grid2">${input('deliveryDate',t('deliveryDate'),'date',dateValue,true,'','min="2000-01-01" max="2200-12-31"')}<div class="field"><label for="f-deliverySlot">${t('deliverySlot')}</label><select id="f-deliverySlot" name="deliverySlot" required><option value="">${t('chooseDeliverySlot')}</option>${deliverySlotOptions.map(slot=>`<option value="${slot.value}" ${window?.scheduledAt.slice(11)===slot.value?'selected':''}>${slot.value}–${slot.end}${slot.nextDay?' ('+t('nextDay')+')':''}</option>`).join('')}</select></div></div><p class="muted schedule-hint">${t('deliverySlotHint')}</p>${originalSchedule(o)?`<div class="notice">${t('originalSchedule')}: ${e(originalSchedule(o))}${window?'<br>'+t('deliverySlot')+': '+e(schedule(o)):''}</div>`:''}`;
}
function badge(status){return `<span class="badge ${status}">${t(status)}</span>`;}
function orderCard(o){return `<article class="order-card" data-order-id="${e(o.id)}"><div class="order-head"><div><span class="order-number">#${e(o.number)}</span><span class="order-date">${e(o.customer||t('noCustomer'))}</span></div>${badge(o.status)}</div>${buyerPayment(o)}<div class="order-timing" data-timing-id="${e(o.id)}">${timingHtml(o)}</div><div class="order-main"><div class="order-items">${o.items.map(i=>`${itemLabel(i)} <span class="muted">× ${i.quantity}</span>`).join('<br>')}<small>${e(o.preference||t('noPreference'))}</small><div class="prep-estimate">${estimateHtml(o)}</div>${materialsHtml(aggregateMaterials([o],account().menu),true)}</div><div><div class="detail-label">${t('scheduled')}</div><div class="detail-value">${schedule(o)}</div><div class="detail-label" style="margin-top:8px">${t('contact')}</div><div class="detail-value">${e(o.contact)}</div></div><div><div class="detail-label">${t('location')}</div><div class="detail-value">${e(o.location)}</div></div></div><div class="order-foot"><div class="order-note">${e(o.notes||t('noNotes'))}</div><div class="row">${button('view-order',t('view'),'small',`data-id="${o.id}"`)}${isActiveOrder(o)?button('edit-order',t('edit'),'small',`data-id="${o.id}"`)+button('deliver',t('markDelivered'),'primary small',`data-id="${o.id}"`):''}</div></div></article>`;}
function menuPage(a){return `<header class="page-head"><div><div class="eyebrow">${t('tag')}</div><h1>${t('menuTitle')}</h1><p>${t('menuSub')}</p></div><div class="row wrap menu-actions">${button('import-menu-ai',t('menuImportTitle'))}${button('export-menu',t('menuExportTitle'),'',a.menu.length?'':'disabled')}${button('add-dish',t('addDish'),'primary')}</div></header>${a.menu.length?`<section class="menu-grid">${a.menu.map(d=>`<article class="dish"><img class="dish-photo" src="${e(d.image)}" alt="${e(d.name)}"><div class="dish-body"><h3>${e(d.name)}</h3><p>${validCents(d.priceCents)?dualMoney(d.priceCents):t('unpriced')}</p>${d.category?'<span class="badge">'+e(d.category)+'</span>':''}${d.aliases?.length?`<p class="dish-aliases"><b>${t('aliases')}:</b> ${d.aliases.map(e).join(' · ')}</p>`:''}<p>${e(d.description)}</p><div class="detail-label">${t('ingredients')}</div><div class="detail-value">${recipeHtml(d.ingredients)}</div><div class="row between dish-bottom"><span class="badge">${d.minutes} ${t('minutes')}</span><div class="row">${button('edit-dish',t('edit'),'small ghost',`data-id="${d.id}"`)}${button('delete-dish',t('delete'),'small ghost danger',`data-id="${d.id}"`)}</div></div></div></article>`).join('')}</section>`:empty('emptyMenu','emptyMenuSub','add-dish','addDish')}`;}

function ingredientRow(row={}){
  return `<div class="recipe-row"><label><span>${t('materialName')}</span><input name="materialName" list="material-names" value="${e(row.name||'')}" required maxlength="80" placeholder="${t('materialExample')}"></label><label><span>${t('perServingQuantity')}</span><input name="materialQuantity" type="number" min="0.001" max="1000000" step="0.001" value="${row.quantity??''}" required></label><label><span>${t('materialUnit')}</span><select name="materialUnit" required><option value="">${t('chooseUnit')}</option>${materialUnits.map(unit=>`<option value="${unit}" ${unit===(row.unit||(row.name?'':'g'))?'selected':''}>${t('unit_'+unit)}</option>`).join('')}</select></label>${button('remove-material','×','ghost',`aria-label="${t('removeMaterial')}"`)}</div>`;
}
function amount(value){return new Intl.NumberFormat(languageConfig(language).locale,{maximumFractionDigits:6}).format(value);}
function recipeText(ingredients){return recipeRows(ingredients).map(row=>row.name+(row.quantity&&row.unit?' '+amount(row.quantity)+' '+t('unit_'+row.unit):' ('+t('quantityUnknown')+')')).join(' · ');}
function recipeHtml(ingredients){return e(recipeText(ingredients));}
function materialsHtml(result,compact=false){
  return `<div class="materials-result ${compact?'compact':''}">${compact?`<div class="detail-label">${t('orderMaterials')}</div>`:''}${result.totals.length?`<ul class="material-list">${result.totals.map(row=>`<li><span>${e(row.name)}</span><b>${amount(row.quantity)} ${t('unit_'+row.unit)}</b></li>`).join('')}</ul>`:''}${result.estimated?`<p class="material-warning">${t('estimatedRecipe')}</p>`:''}${result.missing.length?`<details class="material-warning" open><summary>${t('missingMaterials')} (${result.missing.length})</summary><ul>${result.missing.map(row=>`<li>${e(row.name||t('recipeUnknown'))} — ${e(row.dish)} × ${row.servings} · ${t('quantityUnknown')}</li>`).join('')}</ul></details>`:''}${!result.totals.length&&!result.missing.length?`<p class="muted">${t('noMaterials')}</p>`:''}</div>`;
}
function materialsPage(a){
  const orders=materialOrders(a.orders,materialScope),result=aggregateMaterials(orders,a.menu);
  return `<header class="page-head"><div><div class="eyebrow">${t('tag')}</div><h1>${t('materials')}</h1><p>${t('materialsSub')}</p></div></header><div class="filters" role="group" aria-label="${t('materials')}">${['current','today'].map(scope=>button('material-scope',t(scope==='current'?'currentMaterials':'todayMaterials'),materialScope===scope?'active':'',`aria-pressed="${materialScope===scope}" data-scope="${scope}"`)).join('')}</div><section class="materials-panel"><h2>${t(materialScope==='current'?'currentMaterials':'todayMaterials')}</h2><p class="muted">${t(materialScope==='current'?'currentMaterialsHelp':'todayMaterialsHelp')}</p><p>${t('materialOrderCount')}: <b>${orders.length}</b> · ${new Date().toLocaleDateString(languageConfig(language).locale)}</p>${materialsHtml(result)}<p class="muted">${t('materialsAccountingHelp')}</p></section>`;
}

function openModal(title,body,foot='',onClose=true){if(modal.open)modal.close();modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2>${onClose?button('close-modal','×','close',`aria-label="${t('close')}"`):''}</div>${body}${foot}`;modal.showModal();modal.scrollTop=0;}
function footer(label,formId){return `<div class="modal-foot sticky">${button('close-modal',t('cancel'))}<button type="submit" form="${formId}" class="primary">${label}</button></div>`;}
function menuWelcome(){openModal(t('menuPrompt'),`<div class="modal-body"><div class="notice">${t('menuPromptText')}</div>${button('setup-menu',t('setupMenu'),'primary wide')}</div>`);}
function confirmAction(title,text,details,callback){confirmCallback=callback;confirmation.innerHTML=`<div class="modal-head"><h2 id="confirm-title">${title}</h2>${button('cancel-confirm','×','close',`aria-label="${t('close')}"`)}</div><div class="modal-body"><p class="confirm-text">${text}</p>${details?`<div class="confirm-details">${e(details)}</div>`:''}</div><div class="modal-foot">${button('cancel-confirm',t('cancel'))}${button('accept-confirm',t('confirm'),'primary')}</div>`;confirmation.showModal();confirmation.querySelector('[data-action=cancel-confirm]').focus();}
function dishForm(id,draft,onReviewed){logEvent('form_dish',id||'new');const d=account().menu.find(x=>x.id===id)||draft;photo=d?.image||'';openModal(t(onReviewed?'batchEdit':d?'editDish':'newDish'),`<form id="dish-form" ${onReviewed?'data-menu-review':''}><div class="modal-body">${input('name',t('dishName'),'text',d?.name,true,'','maxlength="100"')}${textarea('aliases',t('aliases'),(d?.aliases||[]).join('\n'),false,`maxlength="2200" placeholder="${e(t('aliasesPlaceholder'))}"`)}<p class="muted aliases-hint">${t('aliasesHint')}</p>${textarea('description',t('dishDescription'),d?.description,false,'maxlength="2000"')}${pricingFields(d,t,e,[...new Set(account().menu.map(d=>d.category).filter(Boolean))])}<fieldset class="recipe-editor"><legend>${t('recipePerServing')}</legend><p class="muted">${t('recipeHelp')}</p>${typeof d?.ingredients==='string'?`<div class="notice">${t('legacyRecipeHelp')}<br>${e(d.ingredients)}</div>`:''}<datalist id="material-names">${[...new Set(account().menu.flatMap(d=>recipeRows(d.ingredients).map(r=>r.name)))].map(name=>`<option value="${e(name)}"></option>`).join('')}</datalist><div id="recipe-rows">${(recipeRows(d?.ingredients).length?recipeRows(d.ingredients):[{}]).map(ingredientRow).join('')}</div>${button('add-material',t('addMaterial'),'small ghost')}</fieldset>${input('minutes',t('duration'),'number',onReviewed?(d?.minutes??''):(d?.minutes||15),true,'','min="1" max="1440" step="1"')}<div class="field"><label for="dish-image">${t('image')}</label><input id="dish-image" type="file" accept="image/jpeg,image/png,image/webp" aria-describedby="image-hint"><small id="image-hint">${t('imageHint')}</small><img id="image-preview" class="photo-preview ${photo?'':'hidden'}" src="${e(photo)}" alt="${t('image')}"></div>${onReviewed?`<button type="button" data-use-placeholder>${t('menuImportPlaceholder')}</button>`:''}<p id="dish-error" class="error" role="alert"></p></div></form>`,footer(t(onReviewed?'menuImportReviewed':d?'saveChanges':'saveDish'),'dish-form'));
  wirePricingEditor(document.querySelector('#dish-form'),t,e);
  modal.querySelector('[data-use-placeholder]')?.addEventListener('click',()=>{const canvas=document.createElement('canvas');canvas.width=160;canvas.height=100;const ctx=canvas.getContext('2d');ctx.fillStyle='#edf0ed';ctx.fillRect(0,0,160,100);photo=canvas.toDataURL('image/png');const preview=modal.querySelector('#image-preview');preview.src=photo;preview.classList.remove('hidden');modal.querySelector('#dish-error').textContent='';});
  document.querySelector('#dish-image').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;const submit=modal.querySelector('[type=submit]');submit.disabled=true;try{photo=await compressPhoto(file);const preview=document.querySelector('#image-preview');preview.src=photo;preview.classList.remove('hidden');document.querySelector('#dish-error').textContent='';}catch(err){document.querySelector('#dish-error').textContent=err.message;event.target.value='';}finally{submit.disabled=false;}});
  document.querySelector('#dish-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget),error=document.querySelector('#dish-error');const dish={...(d?.batchId?{batchId:d.batchId,batchEntryId:d.batchEntryId}:{}),id:d?.id||uid(),name:String(data.get('name')).trim(),description:String(data.get('description')).trim(),ingredients:[],minutes:Number(data.get('minutes')),image:photo};try{Object.assign(dish,readPricing(event.currentTarget));}catch(err){error.textContent=cloudMessage(err);return;}if(!photo){error.textContent=t('imageRequired');return}try{dish.ingredients=validateRecipe([...event.currentTarget.querySelectorAll('.recipe-row')].map(row=>({name:row.querySelector('[name=materialName]').value,quantity:Number(row.querySelector('[name=materialQuantity]').value),unit:row.querySelector('[name=materialUnit]').value})));}catch{error.textContent=t('invalidRecipe');return}if(!dish.name){error.textContent=t('required');return}if(!Number.isInteger(dish.minutes)||dish.minutes<1||dish.minutes>1440){error.textContent=t('dishBadDuration');return}try{dish.aliases=cleanAliases(String(data.get('aliases')||''),dish.name);}catch(err){error.textContent=t(err.message==='ALIAS_LIMIT'?'aliasesLimit':'aliasesLength');return;}const conflict=conflictingDish(account().menu,dish);if(conflict){error.textContent=t('aliasesConflict')+' '+conflict.name;return;}if(onReviewed){onReviewed(dish);return;}const save=async()=>{const next=structuredClone(account()),first=!next.menu.length;if(d)next.menu=next.menu.map(x=>x.id===dish.id?dish:x);else next.menu.push(dish);if(await saveAccount(next)){modal.close();if(first)view='orders';render();toast(t('saved'));}};if(d)confirmAction(t('confirmDishSave'),t('confirmDishText'),dish.name+'\n'+t('priceLabel')+': '+money(dish.priceCents,languageConfig(language).locale)+'\n'+t('categoryLabel')+': '+(dish.category||t('uncategorized'))+'\n'+dish.optionGroups.map(g=>g.name+': '+g.choices.map(c=>c.name+' +'+money(c.priceCents,languageConfig(language).locale)).join(' / ')).join('\n')+'\n'+t('aliases')+': '+dish.aliases.join(' · ')+'\n'+t('recipePerServing')+': '+recipeText(dish.ingredients),save);else save();});}
async function compressPhoto(file,maxDimension=800){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error(t('imageInvalid'));let bitmap;try{bitmap=await createImageBitmap(file);const ratio=Math.min(1,maxDimension/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.75);}catch{throw Error(t('imageFailed'));}finally{bitmap?.close();}}
function addOrder(){opsUI.addOrder();}
function itemRow(item={},menuOnly=false){
  const review=needsItemReview(item),noticeOnly=['alias','similar'].includes(item.matchType),checkId='match-'+uid(),menuDish=findMenuDish(account().menu,item.name),suggested=suggestedMenuName(item,account().menu);
  const candidates=(item.candidates||[]).filter(c=>account().menu.some(d=>d.id===c.dishId&&d.name===c.name));
  return `<div class="item-row" data-item="${e(JSON.stringify(item))}"><input name="itemName" list="menu-options" value="${e(menuOnly&&!menuDish?'':item.name)}" placeholder="${t(menuOnly?'chooseMenuDish':'dishPlaceholder')}" required maxlength="100" aria-label="${t('dishName')}"><input name="itemQuantity" type="number" min="1" max="999" step="1" value="${item.quantity??1}" required aria-label="${t('quantity')}">${button('remove-item','×','ghost',`aria-label="${t('removeItem')}"`)}${menuOnly?`<div class="menu-dish-picker"><label for="${checkId}-select">${t('chooseMenuDish')}</label><select id="${checkId}-select" class="menu-dish-select" aria-label="${t('chooseMenuDish')}"><option value="">${t('chooseMenuDish')}</option>${account().menu.map(d=>`<option value="${d.id}" ${menuDish?.id===d.id?'selected':''}>${e(d.name)}</option>`).join('')}</select></div>`:''}${noticeOnly?`<div class="match-notice"><b>${t(item.matchType==='alias'?'matchAlias':'matchSimilar')}</b><div>${e(item.originalName)} → ${e(suggested||item.name)}</div><p>${t('matchNoticeOnly')}</p></div>`:''}${review?`<div class="match-review"><b class="match-badge">${t(item.matchType==='guessed'?'matchGuessed':'matchUnmatched')}</b><div>${t('matchOriginal')}: <strong>${e(item.originalName||item.name)}</strong></div><div>${t('matchSuggested')}: <strong>${suggested?e(suggested):t('noMenuSuggestion')}</strong></div><p>${e(rt(item.matchReason))}</p>${candidates.length>1?`<div class="match-candidates"><span>${t('matchCandidates')}</span>${candidates.map(c=>button('choose-match',e(c.name),'small',`data-name="${e(c.name)}"`)).join('')}</div>`:''}<p class="match-current">${t(menuOnly&&!menuDish?'menuItemRequired':'matchCanEdit')}</p><label class="match-ack" for="${checkId}"><input id="${checkId}" class="match-check" type="checkbox" required ${menuOnly&&!menuDish?'disabled':''}>${t('matchAcknowledge')}</label></div>`:''}</div>`;
}
function orderForm(id,draft,onReviewed){logEvent('form_order',id||'new');
  const original=account().orders.find(x=>x.id===id),o=original||draft||{},uncertain=(o.items||[]).some(needsItemReview),menuOnly=!!draft||!!o.sourceText||!!o.recognitionMethod||(o.items||[]).some(i=>i.matchType);
  openModal(t(original?'editOrder':draft?'reviewOrder':'newOrder'),`<form id="order-form" data-menu-only="${menuOnly}"><div class="modal-body">
    ${draft?`<div class="notice">${t('importReviewNotice')}${!draft.items.length?`<br>${t('noMatchedDishes')}`:''}</div>`:''}
    ${draft?.warnings?.length?`<div class="notice">${draft.warnings.map(v=>e(rt(v))).join('<br>')}</div>`:''}
    <div class="field"><div class="items-heading">${t('orderItems')}</div><datalist id="menu-options">${account().menu.map(d=>`<option value="${e(d.name)}"></option>`).join('')}</datalist><div id="item-rows">${(o.items?.length?o.items:[{}]).map(item=>itemRow(item,menuOnly)).join('')}</div>${button('add-item',t('addItem'),'small ghost')}</div>
    ${scheduleInputs(o,!!draft)}${input('customer',t('customer'),'text',o.customer,false,'','maxlength="100"')}
    ${input('location',t('location'),'text',o.location,true,'','maxlength="500"')}${input('contact',t('contact'),'text',o.contact,true,'','maxlength="200"')}${input('preference',t('preference'),'text',o.preference,false,'','maxlength="500"')}${textarea('notes',t('notes'),o.notes,false,'maxlength="3000"')}
    ${original&&o.status!=='delivered'?`<div class="field"><label for="order-status">${t('status')}</label><select id="order-status" name="status">${['pending','preparing','delivering'].map(s=>`<option value="${s}" ${s===o.status?'selected':''}>${t(s)}</option>`).join('')}</select></div>`:''}
    ${o.sourceText?`<details ${uncertain?'open':''}><summary>${t('sourceText')}</summary><p class="detail-value" style="white-space:pre-wrap">${e(o.sourceText)}</p></details>`:''}<p id="order-error" class="error" role="alert"></p></div></form>`,footer(t(original?'saveChanges':draft?'reviewAndContinue':'saveOrder'),'order-form'));
  const form=document.querySelector('#order-form');
  if(original?.source==='buyer'){for(const control of form.querySelectorAll('#item-rows input,#item-rows select,#item-rows button'))control.disabled=true;form.querySelector('[data-action=add-item]').hidden=true;form.querySelector('#item-rows').insertAdjacentHTML('afterend','<p class="notice">'+t('paidOrderLocked')+'</p>');}
  if(onReviewed){modal.dataset.batchView='edit';modal.querySelector('button[type=submit]').textContent=t('batchReviewDone');}
  function resetReview(row){const input=row.querySelector('[name=itemName]'),dish=findMenuDish(account().menu,input.value),picker=row.querySelector('.menu-dish-select');if(picker)picker.value=dish?.id||'';input.setCustomValidity(menuOnly&&!dish?t('menuItemRequired'):'');const checkbox=row.querySelector('.match-check');if(checkbox){checkbox.checked=false;checkbox.disabled=menuOnly&&!dish;row.querySelector('.match-current').textContent=menuOnly&&!dish?t('menuItemRequired'):t('matchChanged')+' '+(dish?.name||input.value)+' × '+row.querySelector('[name=itemQuantity]').value;}}
  form.addEventListener('input',event=>{if(['itemName','itemQuantity'].includes(event.target.name))resetReview(event.target.closest('.item-row'));});
  form.addEventListener('click',event=>{const candidate=event.target.closest('[data-action=choose-match]');if(candidate){const row=candidate.closest('.item-row');row.querySelector('[name=itemName]').value=candidate.dataset.name;resetReview(row);row.querySelector('[name=itemName]').focus();}});
  form.addEventListener('change',event=>{if(event.target.classList.contains('menu-dish-select')){const row=event.target.closest('.item-row'),dish=account().menu.find(d=>d.id===event.target.value);row.querySelector('[name=itemName]').value=dish?.name||'';resetReview(row);}});
  for(const row of form.querySelectorAll('.item-row')){const input=row.querySelector('[name=itemName]');input.setCustomValidity(menuOnly&&!findMenuDish(account().menu,input.value)?t('menuItemRequired'):'');}
  form.addEventListener('submit',event=>{
    event.preventDefault();const data=new FormData(form),reviewedAt=new Date().toISOString(),items=[];
    if(original?.source==='buyer')items.push(...structuredClone(original.items));else for(const row of form.querySelectorAll('.item-row')){
      const name=row.querySelector('[name=itemName]').value.trim(),quantity=Number(row.querySelector('[name=itemQuantity]').value),source=JSON.parse(row.dataset.item||'{}');
      try{const item=applyItemReview(source,name,quantity,account().menu,!!row.querySelector('.match-check')?.checked,reviewedAt,menuOnly);const old=original?.items.find(i=>i.name===name);if(old&&old.name===item.name)item.minutes=old.minutes;items.push(snapshotItem(item,account().menu,source,!!original));}catch(error){const badMenu=error.message==='MENU_ITEM_REQUIRED';document.querySelector('#order-error').textContent=t(badMenu?'menuItemRequired':'matchReviewRequired');row.querySelector(badMenu?'[name=itemName]':'.match-check')?.focus();return;}
    }
    const selectedWindow=slotForTime(String(data.get('deliveryDate'))+'T'+String(data.get('deliverySlot')));
    const order={...o,id:original?.id||uid(),number:original?.number||`${localDateTime(new Date()).slice(0,10).replaceAll('-','')}-${String(account().orders.length+1).padStart(3,'0')}`,items,customer:String(data.get('customer')).trim(),location:String(data.get('location')).trim(),contact:String(data.get('contact')).trim(),preference:String(data.get('preference')).trim(),notes:String(data.get('notes')).trim(),scheduledAt:selectedWindow?.scheduledAt||'',scheduledEndAt:selectedWindow?.scheduledEndAt||'',status:original?String(data.get('status')||original.status):'pending',createdAt:original?.createdAt||reviewedAt,updatedAt:reviewedAt};
    const invalid=validateOrder(order);if(invalid){document.querySelector('#order-error').textContent=t({items:'missingItems',quantity:'badQuantity',scheduledAt:'missingTime',location:'missingLocation',contact:'missingContact'}[invalid]);return;}
    if(onReviewed){onReviewed(order);return;}
    const save=async()=>{const next=structuredClone(account());if(draft){order.merchantConfirmedAt=new Date().toISOString();order.requiresMerchantConfirmation=false;for(const item of order.items)if(item.matchType)item.merchantReviewedAt=order.merchantConfirmedAt;}if(original)next.orders=next.orders.map(x=>x.id===original.id?order:x);else next.orders.push(order);if(await saveAccount(next)){modal.close();view='orders';if(!original){filter='active';search='';}render();toast(t(original?'orderUpdated':'orderSaved'));}};
    if(original)confirmAction(t('confirmSave'),t('confirmSaveText'),orderSummary(order),save);
    else if(draft)confirmAction(t('confirmImportedOrder'),t('confirmImportedText'),orderSummary(order)+'\n'+items.filter(i=>i.matchType).map(i=>`${t('matchOriginal')}: ${i.originalName} → ${i.name}${i.merchantCorrected?' ('+t('matchCorrected')+')':''}`).join('\n'),save);
    else save();
  });
}
async function merchantRequest(action,extra={}){const state=action?await cloudRequest({action,merchantId:currentId,expectedRevision:revision,...extra}):await cloudRequest({},'?merchantId='+encodeURIComponent(currentId));acceptState(state);return state;}
async function beginBatchTracking(kind,ids,method){const state=await merchantRequest('batch_begin',{kind,entryIds:ids,method});return state.batches.at(-1).id;}
async function recordBatch(id,event,entryId){await merchantRequest('batch_event',{batchId:id,event,entryId});}
async function startBatchReview(result,method){
  const next={accountId:currentId,sourceText:result.sourceText,warnings:result.warnings||[],entries:result.orders.map(draft=>({id:uid(),draft:{...draft,recognitionMethod:method},reviewed:!batchDraftIssue(draft,account().menu)}))};
  try{next.id=await beginBatchTracking('orders',next.entries.map(e=>e.id),method);pendingBatch=next;showBatchReview();}catch(error){toast(cloudMessage(error));}
}
function trackedOrders(batch){return prepareBatchOrders(batch.entries,account().menu,account().orders).map((order,i)=>({...order,batchId:batch.id,batchEntryId:batch.entries[i].id}));}
function showBatchReview(){
  if(!pendingBatch||pendingBatch.accountId!==currentId)return;
  const entries=pendingBatch.entries;
  openModal(t('batchTitle')+` (${entries.length})`,`<div class="modal-body"><div class="notice">${t('batchNotice')}</div>${pendingBatch.warnings.length?`<div class="notice">${pendingBatch.warnings.map(v=>e(rt(v))).join('<br>')}</div>`:''}<div class="batch-list">${entries.map((entry,index)=>{
    const o=entry.draft,issue=batchDraftIssue(o,account().menu),ready=!issue;
    return `<article class="batch-card"><h3>${t('batchOrder')} ${index+1} · ${e(o.customer||t('noCustomer'))}</h3><div class="batch-summary">${e(orderSummary({...o,number:String(index+1)}))}</div>${o.items.filter(i=>['alias','similar'].includes(i.matchType)).map(i=>`<div class="match-notice"><b>${t(i.matchType==='alias'?'matchAlias':'matchSimilar')}</b><div>${e(i.originalName)} → ${e(i.name)}</div><small>${t('matchNoticeOnly')}</small></div>`).join('')}${o.warnings?.length?`<div class="notice">${o.warnings.map(v=>e(rt(v))).join('<br>')}</div>`:''}${issue?`<p class="error">${t({menu:'menuItemRequired',match:'matchReviewRequired',items:'missingItems',quantity:'badQuantity',scheduledAt:'missingTime',location:'missingLocation',contact:'missingContact'}[issue])}</p>`:''}<div class="row">${button('batch-edit',t('batchEdit'),'small',`data-id="${entry.id}"`)}${button('batch-remove',t('batchRemove'),'small ghost',`data-id="${entry.id}"`)}</div><p class="batch-ready">${t(ready&&entry.reviewed?'batchReady':'batchNeedsReview')}</p><details><summary>${t('sourceText')}</summary><p class="detail-value" style="white-space:pre-wrap">${e(o.sourceText||pendingBatch.sourceText)}</p></details></article>`;
  }).join('')}</div>${!entries.length?`<p>${t('batchEmpty')}</p>`:''}<p id="batch-error" class="error" role="alert"></p></div><div class="modal-foot sticky">${button('close-modal',t('batchDiscard'))}${button('batch-confirm',t('batchConfirm'),'primary',!entries.length||entries.some(x=>!x.reviewed||batchDraftIssue(x.draft,account().menu))?'disabled':'')}</div>`);
  modal.dataset.batchView='list';

}
function closeOrderModal(){
  if(menuImporter.close())return;
  if(!pendingBatch||!modal.dataset.batchView){modal.close();logEvent('close_dialog');return;}
  if(modal.dataset.batchView==='edit'){showBatchReview();return;}
  confirmAction(t('batchDiscard'),t('batchDiscardText'),'',async()=>{const batch=pendingBatch;try{await recordBatch(batch.id,'discard');if(pendingBatch!==batch)return;pendingBatch=null;delete modal.dataset.batchView;modal.close();}catch(error){toast(cloudMessage(error));}});
}
async function batchAction(name,id){
  if(!pendingBatch||pendingBatch.accountId!==currentId)return;const batch=pendingBatch,entry=batch.entries.find(x=>x.id===id);
  try{
    if(name==='batch-edit'&&entry)orderForm(null,entry.draft,async draft=>{try{await recordBatch(batch.id,'edit',entry.id);entry.draft=draft;entry.reviewed=true;showBatchReview();}catch(error){toast(cloudMessage(error));}});
    if(name==='batch-remove'&&entry){await recordBatch(batch.id,'remove',entry.id);batch.entries=batch.entries.filter(x=>x.id!==id);showBatchReview();}
    if(name==='batch-confirm'){
      try{trackedOrders(batch);}catch{document.querySelector('#batch-error').textContent=t('batchRequired');return;}
      confirmAction(t('batchConfirmTitle'),t('batchConfirmText'),batch.entries.map((x,i)=>orderSummary({...x.draft,number:String(i+1)})).join('\n\n'),async()=>{
        if(pendingBatch!==batch||currentId!==batch.accountId)return;
        let orders;try{orders=trackedOrders(batch);}catch{showBatchReview();document.querySelector('#batch-error').textContent=t('batchRequired');return;}
        const next=structuredClone(account());next.orders.push(...orders);if(await saveAccount(next,false,{batchId:batch.id})){pendingBatch=null;delete modal.dataset.batchView;modal.close();view='orders';filter='active';search='';render();toast(t('batchSaved')+' '+orders.length);}
      });
    }
  }catch(error){toast(cloudMessage(error));}
}
function reviewHistory(o){
  const items=(o.items||[]).filter(i=>i.matchType);if(!items.length)return '';
  return `<details class="review-history"><summary>${t('matchHistory')}</summary>${items.map(i=>`<p>${t('matchOriginal')}: ${e(i.originalName)}<br>${t('matchSuggested')}: ${i.matchType==='unmatched'?t('noMenuSuggestion'):e(i.recognizedName||i.name)}<br>${t('dishName')}: ${e(i.name)} × ${i.quantity}${i.merchantCorrected?' · '+t('matchCorrected'):''}<br>${e(rt(i.matchReason||''))}</p>`).join('')}${o.merchantConfirmedAt?`<p>${t('matchConfirmed')}: ${date(o.merchantConfirmedAt)}</p>`:''}</details>`;
}
function orderSummary(o){return `#${o.number}\n${o.items.map(i=>`${i.name} × ${i.quantity}${optionText(i)?' ('+optionText(i)+')':''}`).join('、')}\n${t('scheduled')}: ${schedule(o)}${originalSchedule(o)?'\n'+t('originalSchedule')+': '+originalSchedule(o):''}\n${t('customer')}: ${o.customer||t('noCustomer')}\n${t('location')}: ${o.location}\n${t('contact')}: ${o.contact}\n${t('preference')}: ${o.preference||t('noPreference')}\n${t('notes')}: ${o.notes||t('noNotes')}`;}
function viewOrder(id){const o=account().orders.find(x=>x.id===id);if(!o)return;const estimate=o.items.reduce((n,i)=>n+(i.minutes||0)*i.quantity,0);openModal(t('orderDetails'),`<div class="modal-body"><div class="row between" style="margin-bottom:24px"><h3>#${e(o.number)}</h3>${badge(o.status)}</div><div class="field"><div class="detail-label">${t('orderItems')}</div><div class="detail-value">${o.items.map(i=>`${itemLabel(i)} × ${i.quantity}`).join('<br>')}</div></div>${[[t('scheduled'),schedule(o)],...(originalSchedule(o)?[[t('originalSchedule'),originalSchedule(o)]]:[]),[t('created'),date(o.createdAt)],...(o.deliveredAt?[[t('deliveredAt'),date(o.deliveredAt)]]:[]),[t('customer'),o.customer||t('noCustomer')],[t('location'),o.location],[t('contact'),o.contact],[t('preference'),o.preference||t('noPreference')],[t('notes'),o.notes||t('noNotes')],...(estimate?[[t('estimated'),`${estimate} ${t('minutes')} (${t('estimateHint')})`]]:[])].map(([label,value])=>`<div class="field"><div class="detail-label">${label}</div><div class="detail-value" style="white-space:pre-wrap">${e(value)}</div></div>`).join('')}<div class="field"><div class="detail-label">${t('orderMaterials')}</div>${materialsHtml(aggregateMaterials([o],account().menu))}</div>${buyerPayment(o)}${reviewHistory(o)}${o.batchId?`<p class="muted">${t('batchLabel')}: ${e(o.batchId)}</p>`:''}${o.merchantDecision?.reason?`<p>${t('rejectionReason')}: ${e(o.merchantDecision.reason)}</p>`:''}${o.sourceText?`<details><summary>${t('sourceText')}</summary><p class="detail-value" style="white-space:pre-wrap">${e(o.sourceText)}</p></details>`:''}</div>`,`<div class="modal-foot">${button('close-modal',t('close'))}${isActiveOrder(o)?button('edit-order',t('edit'),'primary',`data-id="${o.id}"`):''}</div>`);}
function aiMessage(code){return messages[language]['aiError'+code]||t('aiErrorAI_UNAVAILABLE');}
async function recognitionForm(){await logEvent('recognition_open');
  const rulesLabel=t('rulesOnly');
  const aiLabel=t('extractAI');
  openModal(t('recognitionTitle'),`<form id="recognition-form"><div class="modal-body"><div id="ai-notice" class="notice">${t('checkingAI')}</div><p>${t('batchInputHelp')}</p>${textarea('source',t('recognitionLabel'),'',true,`class="source-text" maxlength="${TEXT_LIMIT}" placeholder="${e(t('recognitionPlaceholder'))}"`)}${documentField(t)}<p id="recognition-error" class="error" role="alert"></p>${button('use-basic-rules',rulesLabel,'small ghost')}</div></form>`,footer(aiLabel,'recognition-form'));
  const form=document.querySelector('#recognition-form'),source=form.querySelector('#f-source'),error=form.querySelector('#recognition-error'),submit=modal.querySelector('[type=submit]'),notice=form.querySelector('#ai-notice');
  submit.disabled=true;let configured=false;
  const isCurrent=()=>modal.open&&document.querySelector('#recognition-form')===form;
  function readSource(){const text=source.value.trim();if(text.length>TEXT_LIMIT){error.textContent=t('document_TOO_LARGE');return null;}if(!text){error.textContent=t('emptyText');source.focus();return null}return text;}
  form.querySelector('[data-action=use-basic-rules]').addEventListener('click',()=>{const text=readSource();if(text){logEvent('recognition_rules');}if(text)startBatchReview({orders:[parseOrderText(text,account().menu)],sourceText:text,warnings:[t('batchRulesNotice')]},'rules');});
  const reading=wireDocumentImport({form,source,input:form.querySelector('#text-file'),error,t,confirmAction,isCurrent,busy:value=>{submit.disabled=value||!configured;form.querySelector('[data-action=use-basic-rules]').disabled=value;}});
  form.addEventListener('submit',async event=>{event.preventDefault();if(!configured||reading())return;const text=readSource();if(!text)return;submit.disabled=true;submit.textContent=t('busy');error.textContent='';form.querySelector('[data-action=use-basic-rules]').disabled=true;source.readOnly=true;form.querySelector('#text-file').disabled=true;try{await logEvent('recognition_start');const result=await recognizeWithAI(text,account().menu,currentId);if(!isCurrent())return;await logEvent('recognition_success');await startBatchReview(result,'ai');}catch(err){await logEvent('recognition_failure');if(isCurrent())error.textContent=aiMessage(err.message);}finally{submit.disabled=false;submit.textContent=aiLabel;form.querySelector('[data-action=use-basic-rules]').disabled=false;source.readOnly=false;form.querySelector('#text-file').disabled=false;}});
  try{const status=await getAIStatus();if(!isCurrent())return;configured=status.configured;submit.disabled=!configured||reading();notice.textContent=configured?t('aiReady'):aiMessage('AI_NOT_CONFIGURED');}catch(err){if(isCurrent())notice.textContent=aiMessage(err.message);}
}

function estimateHtml(order){const value=preparationEstimate(order);return t('estimated')+': '+(value.minutes?amount(value.minutes)+' '+t('minutes'):'—')+(value.incomplete?' · '+t('estimateIncomplete'):'')+' <span class="muted">('+t('estimateHint')+')</span>';}
function timingHtml(order){const timing=orderTiming(order);if(['complete','unknown'].includes(timing.state))return '';const seconds=Math.ceil(Math.abs(timing.remainingMs)/1000),minutes=Math.floor(seconds/60),rest=String(seconds%60).padStart(2,'0');return `<span class="countdown-label">${t(timing.state==='overdue'?'deliveryOverdue':'deliveryCountdown')}: <b>${minutes}:${rest}</b></span><span class="muted">${t('countdownBasis')}</span>`;}
function updateOrderTiming(){if(!currentId||view!=='orders')return;for(const node of document.querySelectorAll('[data-order-id]')){const order=account()?.orders.find(o=>o.id===node.dataset.orderId);if(!order)continue;const timing=orderTiming(order);node.classList.toggle('urgent',timing.state==='urgent');node.classList.toggle('overdue',timing.state==='overdue');const label=node.querySelector('[data-timing-id]');if(label)label.innerHTML=timingHtml(order);}}
async function showLogs(cursor=null,append=false){try{const result=await cloudRequest({},'?merchantId='+encodeURIComponent(currentId)+'&logs=1'+(cursor?'&cursor='+encodeURIComponent(cursor):''));logsCursor=result.nextCursor;const rows=result.entries.map(row=>`<article class="audit-row"><time datetime="${e(row.at)}">${new Date(row.at).toLocaleString(languageConfig(language).locale,{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false})}</time><b>${e(row.actor_name)}</b><span>${t('audit_'+row.action)}</span><small>${e(row.target)}${row.details?'<br>'+t('batchKind_'+row.details.kind)+' · '+t('batchOperationCount')+': '+row.details.count+(row.details.entryId?'<br>ID: '+e(row.details.entryId):''):''}</small><small class="muted">ID: ${e(row.actor_id)}</small></article>`).join('');if(append){document.querySelector('#audit-rows').insertAdjacentHTML('beforeend',rows);const more=document.querySelector('[data-action=logs-more]');if(more)more.disabled=!logsCursor;return;}openModal(t('operationLogs'),`<div class="modal-body"><p class="muted">${t('auditHelp')}</p><div id="audit-rows">${rows||t('noLogs')}</div></div>`,`<div class="modal-foot">${button('close-modal',t('close'))}${button('logs-more',t('loadMore'),'small',logsCursor?'':'disabled')}</div>`);}catch(error){toast(cloudMessage(error));}}
async function showOperators(){
 try{const a=account(),result=await cloudRequest({},'?merchantId='+encodeURIComponent(currentId)+'&operators=1');openModal(t('operators'),`<div class="modal-body"><h3>${e(a.shop)} · ${t('inviteCode')}</h3><p>${t('storeCodeHelp')}</p><code class="invite-code">${e(result.storeCode)}</code><p class="muted">${t('operatorAccessHelp')}</p><h3>${t('operators')} (${result.members.length})</h3><p class="muted">${t('accountListHelp')}</p><div class="operator-list">${result.members.map(member=>`<div class="operator-row"><b>${e(member.name)} (${e(member.username)})</b><span>${t('role_'+member.role)} · ${t(member.disabled?'operatorDisabled':'operatorActive')}</span>${member.id===a.operator.id?'<span class="badge">'+t('currentAccount')+'</span>':''}${member.role==='owner'?'<small class="muted">'+t('ownerProtected')+'</small>':a.operator.role==='owner'?button('delete-operator',t('deleteAccount'),'small danger',`data-id="${e(member.id)}" data-name="${e(member.name+' ('+member.username+')')}"`):''}</div>`).join('')}</div></div>`);}catch(error){toast(cloudMessage(error));}
}
function migrationForm(){
 if(account().menu.length||account().orders.length){toast(t('migrationEmptyOnly'));return;}
 openModal(t('migrateLocal'),`<form id="migration-form"><div class="modal-body"><p>${t('migrationHelp')}</p><div class="field"><label for="legacy-account">${t('legacyAccount')}</label><select id="legacy-account" name="legacy">${legacyDb.accounts.map(a=>`<option value="${e(a.id)}">${e(a.shop)} · ${e(a.username)}</option>`).join('')}</select></div>${input('legacyPassword',t('legacyPassword'),'password','',true,'','autocomplete="off"')}<p id="migration-error" class="error"></p></div></form>`,footer(t('migrationReview'),'migration-form'));
 document.querySelector('#migration-form').addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(event.currentTarget),legacy=legacyDb.accounts.find(a=>a.id===data.get('legacy'));try{if(!legacy||await passwordHash(String(data.get('legacyPassword')),legacy.salt)!==legacy.hash)throw Error('LEGACY_PASSWORD');const destination=currentId;confirmAction(t('migrationConfirm'),t('migrationHelp'),legacy.shop+' → '+account().shop+'\n'+t('menu')+': '+legacy.menu.length+' · '+t('orders')+': '+legacy.orders.length,async()=>{if(destination!==currentId)return;const next=structuredClone(account());next.menu=structuredClone(legacy.menu);next.orders=structuredClone(legacy.orders);if(await saveAccount(next,true)){modal.close();render();toast(t('migrationDone'));}});}catch(error){document.querySelector('#migration-error').textContent=cloudMessage(error);}});
}

function exportData(){try{const a=account(),data=JSON.stringify({format:'takeaway-desk-backup-v1',application:'OrderWeave',exportedAt:new Date().toISOString(),shop:a?.shop,username:a?.username,menu:a?.menu||[],orders:a?.orders||[],receivingHours:a?.receivingHours||null,batches:a?.batches||[]},null,2);if(!data)throw Error();const url=URL.createObjectURL(new Blob([data],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=`orderweave-backup-${localDateTime(new Date()).slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast(t('backupDone'));}catch{toast(t('backupReadError'));}}
async function action(ev){const target=ev.target.closest('[data-action]');if(!target)return;const name=target.dataset.action,id=target.dataset.id;if(name==='language')return;if(name==='buyer-enter'){portal='buyer';sessionStorage.setItem('orderweave-portal',portal);await buyerApp.start();}else if(name==='pick-language'){language=resolveLanguage(target.dataset.lang);render();}else if(name==='continue-language'){try{localStorage.setItem(LANG,language);languageChosen=true;render();}catch{toast(t('storageError'));}}else if(name==='retry-demo'){await bootstrap(false);}else if(name.startsWith('auth-')){authMode=name.slice(5);render();}else if(name==='logout'){await logEvent('logout');await cloudRequest({action:'logout'});currentId=null;db={accounts:[]};pendingBatch=null;try{sessionStorage.removeItem(cloudSession);}catch{}authMode='login';await bootstrap(false);}else if(name.startsWith('nav-')){view=name.slice(4);search='';render();await logEvent('view_'+view);}else if(name==='filter'){filter=target.dataset.filter;render();await logEvent('order_filter',filter);}else if(name==='material-scope'){materialScope=target.dataset.scope;render();await logEvent('material_scope',materialScope);}else if(name==='add-material'){const rows=document.querySelector('#recipe-rows');if(rows.children.length>=50){toast(t('invalidRecipe'));return}rows.insertAdjacentHTML('beforeend',ingredientRow());rows.lastElementChild.querySelector('input').focus();}else if(name==='remove-material'){const row=target.closest('.recipe-row');if(row.parentElement.children.length===1)row.outerHTML=ingredientRow();else row.remove();}else if(name==='open-logs'){await logEvent('view_logs');await showLogs();}else if(name==='logs-more')await showLogs(logsCursor,true);else if(name==='open-operators'){await logEvent('view_operators');await showOperators();}else if(name==='migrate-local')migrationForm();else if(name==='delete-operator'){const storeId=currentId;confirmAction(t('deleteAccountTitle'),t('deleteAccountHelp'),target.dataset.name,async()=>{try{await cloudRequest({action:'operator_delete',merchantId:storeId,id});await refreshState(true);await showOperators();toast(t('accountDeleted'));}catch(error){toast(cloudMessage(error));await refreshState();}});}else if(name==='import-menu-ai'){await menuImporter.open();}else if(name==='export-menu'){openMenuExport({account:structuredClone(account()),modal,t,e,locale:languageConfig(language).locale,openModal,toast});}else if(name==='export'){await logEvent('export');exportData();}else if(name==='close-modal')closeOrderModal();else if(name.startsWith('batch-'))batchAction(name,id);else if(name==='cancel-confirm'){confirmation.close();confirmCallback=null;await logEvent('cancel');}else if(name==='accept-confirm'){const callback=confirmCallback;confirmCallback=null;confirmation.close();callback?.();}else if(name==='setup-menu'){view='menu';render();dishForm();}else if(name==='add-dish')dishForm();else if(name==='edit-dish')dishForm(id);else if(name==='delete-dish'){const d=account().menu.find(x=>x.id===id);confirmAction(t('confirmDeleteDish'),t('deleteDishText'),d.name,async()=>{const next=structuredClone(account());next.menu=next.menu.filter(x=>x.id!==id);if(await saveAccount(next)){render();toast(t('saved'));}});}else if(name==='add-order')addOrder();else if(name==='manual'){if(!account().menu.length){menuWelcome();return;}orderForm();}else if(name==='recognition'){if(!account().menu.length){menuWelcome();return;}recognitionForm();}else if(name==='add-item'){document.querySelector('#item-rows').insertAdjacentHTML('beforeend',itemRow({},document.querySelector('#order-form').dataset.menuOnly==='true'));document.querySelector('#item-rows').lastElementChild.querySelector('input').focus();}else if(name==='remove-item'){const row=target.closest('.item-row'),rows=document.querySelectorAll('.item-row');if(rows.length===1){row.outerHTML=itemRow({},document.querySelector('#order-form').dataset.menuOnly==='true');}else row.remove();}else if(name==='edit-order')orderForm(id);else if(name==='view-order'){viewOrder(id);await logEvent('order_view',id);}else if(name==='deliver'){const o=account().orders.find(x=>x.id===id);if(!o||!isActiveOrder(o))return;confirmAction(t('confirmDelivered'),t('confirmDeliveredText'),orderSummary(o),async()=>{const next=structuredClone(account()),order=next.orders.find(x=>x.id===id);order.items=freezeOrderMaterials(order,next.menu).items;order.status='delivered';order.deliveredAt=new Date().toISOString();order.updatedAt=order.deliveredAt;if(await saveAccount(next)){modal.close();render();toast(t('orderDelivered'));}});}}
document.addEventListener('click',action);
document.addEventListener('change',ev=>{if(ev.target.matches('[data-order-sort]')){orderSort=ev.target.value;renderOrderList();updateOrderTiming();}if(ev.target.matches('[data-order-direction]')){orderDirection=ev.target.value;renderOrderList();updateOrderTiming();}if(ev.target.dataset.action==='language'){const next=resolveLanguage(ev.target.value);try{localStorage.setItem(LANG,next);language=next;render();if(currentId)logEvent('language');}catch{toast(t('storageError'));}}});
modal.addEventListener('cancel',event=>{if(menuImporter.active()||pendingBatch&&modal.dataset.batchView){event.preventDefault();closeOrderModal();}});
confirmation.addEventListener('cancel',()=>{confirmCallback=null;});
const buyerApp=createBuyerUI({root:app,modal,t,e,language:()=>language,getLocale:()=>languageConfig(language).locale,langSelect,api:cloudRequest,openModal,confirmAction,toast,compressPhoto:file=>compressPhoto(file,256),onMerchant:async()=>{portal='merchant';sessionStorage.setItem('orderweave-portal',portal);await bootstrap();}});
window.addEventListener('storage',event=>{if(event.key==='orderweave-demo-v1'&&portal==='buyer')buyerApp.refresh().catch(()=>{});});
const opsUI=createMerchantOperationsUI({root:app,modal,t,e,account,locale:()=>languageConfig(language).locale,openModal,confirmAction,request:merchantRequest,render,toast,cloudMessage});
const menuImporter=createMenuImportUI({modal,t,e,account,currentId:()=>currentId,openModal,confirmAction,dishForm,saveAccount,render,toast,aiMessage,beginBatch:ids=>beginBatchTracking('menu',ids,'ai'),recordBatch});
bootstrap();setInterval(()=>{updateOrderTiming();opsUI.updateHours();},1000);setInterval(()=>refreshState(),15000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){updateOrderTiming();refreshState();}});

window.addEventListener('storage',event=>{if(event.key==='orderweave-demo-v1')refreshState();});
